import keyboardUtil from 'src/utils/keyboard';
export default {
  methods: {
    keyDownEvent(e) {
      try {
        const combKey = keyboardUtil.methods.isCtrlKey(e);
        // combKey + Q
        if (e.keyCode === 81 && combKey === true) {
          e.preventDefault();
          const event = new CustomEvent('dashboard_refresh_data', {
            detail: { show_shimmer_loader: true },
          });
          document.dispatchEvent(event);
          return;
        }
        // combKey + K is reserved for global QuickSearch (Cmd+K / Ctrl+K)

        // combKey + H
        if (e.keyCode === 72 && combKey === true) {
          e.preventDefault();
          const event = new CustomEvent('openHelpPage', {});
          document.dispatchEvent(event);
          return;
        }
      } catch (e) {
        logInfo(e);
      }
    },
  },
};
